/**
 * DOMPurify Client-side Sanitizer Module
 * Phiên bản chuẩn cho Lab An ninh mạng - TV2
 * Chức năng: Phân tích cú pháp DOM, bóc tách và loại bỏ hoàn toàn các thẻ độc hại
 * (<script>, <iframe>, <object>, <embed>, <svg>) và các thuộc tính sự kiện (onerror, onload, onclick,...)
 */

(function(root, factory) {
    if (typeof define === 'function' && define.amd) {
        define([], factory);
    } else if (typeof exports === 'object') {
        module.exports = factory();
    } else {
        root.DOMPurify = factory();
    }
}(typeof self !== 'undefined' ? self : this, function() {
    'use strict';

    var DOMPurify = {};

    var ALLOWED_TAGS = [
        'b', 'i', 'em', 'strong', 'u', 'p', 'br', 'ul', 'ol', 'li', 'span'
    ];

    var ALLOWED_ATTRS = ['class'];

    function escapeHTML(str) {
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function decodeBasicEntities(str) {
        return String(str)
            .replace(/&#x([0-9a-f]+);?/gi, function(_, hex) {
                var code = parseInt(hex, 16);
                return code > 0 && code <= 0x10FFFF ? String.fromCodePoint(code) : '';
            })
            .replace(/&#([0-9]+);?/g, function(_, dec) {
                var code = parseInt(dec, 10);
                return code > 0 && code <= 0x10FFFF ? String.fromCodePoint(code) : '';
            });
    }

    /**
     * Kiểm tra URL an toàn theo Allowlist (chặn javascript:, vbscript:, data:, control/tab bypass)
     */
    DOMPurify.isSafeUrl = function(url) {
        if (!url || typeof url !== 'string') return false;
        var decoded = decodeBasicEntities(url);
        var normalized = decoded.replace(/[\x00-\x20\x7f]+/g, '').toLowerCase();
        if (!normalized) return false;
        if (/^(javascript|vbscript|data):/i.test(normalized)) return false;
        return /^(https?:\/\/|\/(?!\/)|#)/i.test(normalized);
    };

    DOMPurify.sanitize = function(dirtyHtml) {
        if (!dirtyHtml || typeof dirtyHtml !== 'string') return '';

        // Loại bỏ ký tự điều khiển ASCII trước khi phân tích
        var cleanedInput = dirtyHtml.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, '');

        try {
            if (typeof DOMParser === 'undefined') {
                return escapeHTML(cleanedInput);
            }
            var parser = new DOMParser();
            var doc = parser.parseFromString(cleanedInput, 'text/html');
            var body = doc.body;

            function cleanNode(node) {
                var children = Array.from(node.childNodes);
                for (var i = 0; i < children.length; i++) {
                    var child = children[i];
                    if (child.nodeType === 8) {
                        // Xóa Comment node để ngăn chặn bypass/mXSS
                        node.removeChild(child);
                        continue;
                    }
                    if (child.nodeType === 1) { // ELEMENT_NODE
                        var tagName = child.tagName.toLowerCase();
                        if (ALLOWED_TAGS.indexOf(tagName) === -1) {
                            // Cơ chế Allowlist nghiêm ngặt: loại bỏ mọi thẻ không nằm trong danh sách cho phép
                            node.removeChild(child);
                            continue;
                        }

                        // Chỉ giữ lại các thuộc tính nằm trong ALLOWED_ATTRS với giá trị hợp lệ
                        var attrs = Array.from(child.attributes);
                        for (var j = 0; j < attrs.length; j++) {
                            var attr = attrs[j];
                            var attrName = attr.name.toLowerCase();
                            var attrVal = attr.value || '';

                            if (ALLOWED_ATTRS.indexOf(attrName) === -1) {
                                child.removeAttribute(attr.name);
                                continue;
                            }
                            if (attrName === 'class' && !/^[a-zA-Z0-9_\-\s]{1,64}$/.test(attrVal)) {
                                child.removeAttribute(attr.name);
                            }
                        }

                        cleanNode(child);
                    }
                }
            }

            cleanNode(body);
            return body.innerHTML;
        } catch (e) {
            // Fallback an toàn: mã hóa HTML thô
            return escapeHTML(cleanedInput);
        }
    };

    DOMPurify.isSupported = true;
    return DOMPurify;
}));
